// This file is automatically generated and enhanced with security middleware.
import { createMiddleware } from '@tanstack/react-start'
import { getRequest } from '@tanstack/react-start/server'
import { createClient } from '@supabase/supabase-js'
import type { Database } from './types'
import { checkRateLimit } from '@/lib/security/rate-limiter'
import { sanitizeString } from '@/lib/security/sanitizer'

export const requireSupabaseAuth = createMiddleware({ type: 'function' }).server(
  async ({ next }) => {
    const SUPABASE_URL = process.env.SUPABASE_URL;
    const SUPABASE_PUBLISHABLE_KEY = process.env.SUPABASE_PUBLISHABLE_KEY;

    if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
      const missing = [
        ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
        ...(!SUPABASE_PUBLISHABLE_KEY ? ['SUPABASE_PUBLISHABLE_KEY'] : []),
      ];
      const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Connect Supabase in Lovable Cloud.`;
      console.error(`[Supabase] ${message}`);
      throw new Response(message, { status: 500 });
    }
    
    const request = getRequest();

    if (!request?.headers) {
      throw new Response('Unauthorized: No request headers available', { status: 401 });
    }

    // IP Rate Limiting
    const clientIp = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 
                     request.headers.get('x-real-ip') || 
                     '127.0.0.1';
    
    const ipRate = checkRateLimit(`ip:${clientIp}`, 60, 60000);
    if (!ipRate.allowed) {
      throw new Response('Too Many Requests: Rate limit exceeded for your IP', { 
        status: 429, 
        headers: { 'Retry-After': String(Math.ceil(ipRate.resetInMs / 1000)) } 
      });
    }

    const authHeader = request.headers.get('authorization');

    if (!authHeader) {
      throw new Response('Unauthorized: No authorization header provided', { status: 401 });
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new Response('Unauthorized: Only Bearer tokens are supported', { status: 401 });
    }

    const rawToken = authHeader.replace('Bearer ', '');
    const token = sanitizeString(rawToken);
    if (!token) {
      throw new Response('Unauthorized: No valid token provided', { status: 401 });
    }

    const supabase = createClient<Database>(
      SUPABASE_URL!,
      SUPABASE_PUBLISHABLE_KEY!,
      {
        global: {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
        auth: {
          storage: undefined,
          persistSession: false,
          autoRefreshToken: false,
        },
      }
    );

    const { data, error } = await supabase.auth.getClaims(token);
    if (error || !data?.claims) {
      throw new Response('Unauthorized: Invalid token', { status: 401 });
    }

    const userId = data.claims.sub;
    if (!userId) {
      throw new Response('Unauthorized: No user ID found in token', { status: 401 });
    }

    // User Rate Limiting
    const userRate = checkRateLimit(`user:${userId}`, 60, 60000);
    if (!userRate.allowed) {
      throw new Response('Too Many Requests: Rate limit exceeded for your user account', { 
        status: 429, 
        headers: { 'Retry-After': String(Math.ceil(userRate.resetInMs / 1000)) } 
      });
    }

    return next({
      context: {
        supabase,
        userId,
        claims: data.claims,
      },
    })
  }
)

